tape( 'the function returns the centroids (row-major)', function test( t ) {
	var expected;
	var data;
	var out;
	var i;

	data = ROW_MAJOR_DATA;
	out = dkmeansInitPlusPlus( data.k, data.M, data.N, new Float64Array( data.out ), data.strideO1, data.strideO2, data.offsetO, new Float64Array( data.X ), data.strideX1, data.strideX2, data.offsetX, data.metric, data.trials, data.seed );

	expected = new Float64Array( data.expected );
	for ( i = 0; i < expected.length; i++ ) {
		t.strictEqual( isAlmostSameValue( out[ i ], expected[ i ], 0 ), true, 'returns expected value' );
	}
	t.end();
});

